import React, { useContext } from 'react';
import { FormattedMessage, useIntl } from 'react-intl';

import { _useId } from '../../../core/hooks/useId.js';
import { Label } from '../../../forms/forms-core/components/label/Label.js';
import { SelectV2 } from '../../../forms/selectv2/Select.js';
import { Flex } from '../../../layouts-core/flex/Flex.js';
import { Text } from '../../../typography/Text.js';
import { TablePaginationContext } from '../../contexts/TablePaginationContext.js';
import { DEFAULT_PAGINATION_PAGE_SIZE } from '../constants.js';
import { dataTableMessages } from '../messages.js';

type PageSizeSelectProps = {
  pageSizeOptions: number[];
  onChange: (value: number | null) => void;
};

export function PageSizeSelect(props: PageSizeSelectProps) {
  const { pageSize = DEFAULT_PAGINATION_PAGE_SIZE } = useContext(
    TablePaginationContext,
  );
  const { pageSizeOptions, onChange } = props;
  const intl = useIntl();

  const rowsPerPageId = _useId();

  return (
    <Flex alignItems="center">
      <SelectV2
        id={rowsPerPageId}
        value={pageSize}
        onChange={onChange}
        aria-label={intl.formatMessage(dataTableMessages.selectPageSize)}
      >
        <SelectV2.Content>
          {pageSizeOptions.map((pageSize) => (
            <SelectV2.Option key={`${pageSize}`} id={pageSize} value={pageSize}>
              {`${pageSize}`}
            </SelectV2.Option>
          ))}
        </SelectV2.Content>
      </SelectV2>
      <Label htmlFor={rowsPerPageId}>
        <Text as="span" textStyle="base" style={{ whiteSpace: 'nowrap' }}>
          <FormattedMessage
            description="Text to display when choosing the number of rows per page."
            defaultMessage="rows per page"
            id="lu2hmVHtfcnVRPtz"
          />
        </Text>
      </Label>
    </Flex>
  );
}
